"""Reproducible starter content. References require executable validation."""
from pathlib import Path
import yaml

root=Path(__file__).resolve().parents[1]/'content'/'challenges'
root.mkdir(parents=True,exist_ok=True)
def write(c):
    c.setdefault('level','intermediate');c.setdefault('minutes',12)
    (root/(c['slug']+'.yaml')).write_text(yaml.safe_dump(c,sort_keys=False,allow_unicode=True),encoding='utf-8')

schemas='CREATE TABLE customers (id INTEGER PRIMARY KEY, name TEXT, email TEXT); CREATE TABLE orders (id INTEGER PRIMARY KEY, customer_id INTEGER, amount REAL);'
base="INSERT INTO customers VALUES (1,'Ada','ada@example.com'),(2,'Lin',NULL),(3,'Sam','sam@example.com'); INSERT INTO orders VALUES (1,1,20),(2,1,30),(3,3,15);"
datasets=[('Sample shop',base, 'sample'),('NULL foreign key',base+' INSERT INTO orders VALUES (4,NULL,80);','hidden'),('Duplicate amounts',base+' INSERT INTO orders VALUES (4,3,15);','hidden'),('No orders',"INSERT INTO customers VALUES (1,'Ada',NULL),(2,'Lin','lin@example.com');",'hidden')]
sqls=[
 ('customers-without-orders','Customers without orders','Return the **id, name** of customers who have no orders, ordered by id. An order may have a NULL customer_id. Every customer should appear at most once.',['joins','null_handling'],"SELECT c.id,c.name FROM customers c LEFT JOIN orders o ON o.customer_id=c.id WHERE o.id IS NULL ORDER BY c.id",'SELECT id, name FROM customers\n-- Find customers who have never ordered\n',[[[2,'Lin']],[[2,'Lin']],[[2,'Lin']],[[1,'Ada'],[2,'Lin']]]),
 ('order-totals','Every customer counts','Return **id, total** for every customer. Sum their order amounts; customers with no orders have total 0. Keep repeated orders: equal amounts can represent different purchases. Order by id.',['aggregation','duplicates','null_handling'],"SELECT c.id,COALESCE(SUM(o.amount),0) AS total FROM customers c LEFT JOIN orders o ON o.customer_id=c.id GROUP BY c.id ORDER BY c.id",'SELECT c.id\nFROM customers c\n-- Include every customer and calculate their total\n',[[[1,50],[2,0],[3,15]],[[1,50],[2,0],[3,15]],[[1,50],[2,0],[3,30]],[[1,0],[2,0]]]),
 ('filter-orders','Find the meaningful orders','Return **id, amount** for orders whose amount is at least 20. Preserve separate orders even when amounts are equal. Sort by amount descending, then id ascending.',['filtering','duplicates'],"SELECT id,amount FROM orders WHERE amount>=20 ORDER BY amount DESC,id ASC",'SELECT id, amount\nFROM orders\n',[[[2,30],[1,20]],[[4,80],[2,30],[1,20]],[[2,30],[1,20]],[]]),
]
for slug,title,statement,comps,reference,starter,expected in sqls:
    write(dict(slug='sql-'+slug,skill='sql',family='sql.'+slug,type='sql',title=title,statement=statement,competencies=comps,language='sql',schema=schemas,sample_rows={'customers':[[1,'Ada','ada@example.com'],[2,'Lin',None],[3,'Sam','sam@example.com']],'orders':[[1,1,20],[2,1,30],[3,3,15]]},starter=starter,reference=reference,hints=['Use the stated output columns and ordering.','Think about NULL values and repeated rows.','For totals, join before grouping; avoid SUM(DISTINCT amount).'],tests=[dict(label=label,dataset=schemas+seed,expected=ex,visibility=vis,competencies=comps) for (label,seed,vis),ex in zip(datasets,expected)]))

for lang in ['python','java','javascript']:
    starters={'python':'def solve(nums):\n    # Return the requested value.\n    return None\n','javascript':'function solve(nums) {\n  // Return the requested value.\n  return null;\n}\n','java':'class Solution {\n    public static Object solve(int[] nums) {\n        // Return the requested value.\n        return null;\n    }\n}\n'}
    tasks=[
        ('second-largest','Second largest, not second last','Return the second largest **distinct** integer in nums, or null if fewer than two distinct values exist. Input is an array of up to 10,000 integers. Do not modify the input.',['collections','algorithms','edge_cases'],[([3,1,4,1,5],4,'A typical collection'),([2,2,2],None,'All values equal'),([],None,'Empty input'),([-1,-5,-3],-3,'Negative values'),([2147483647,-2147483648],-2147483648,'Integer boundaries')],{'python':'def solve(nums):\n    values = sorted(set(nums))\n    return values[-2] if len(values) > 1 else None','javascript':'function solve(nums) { const a=[...new Set(nums)].sort((a,b)=>a-b); return a.length>1?a[a.length-2]:null; }','java':'class Solution { public static Object solve(int[] nums) { java.util.TreeSet<Integer> s=new java.util.TreeSet<>(); for(int n:nums)s.add(n); if(s.size()<2)return null; s.pollLast(); return s.last(); } }'}),
        ('positive-total','A positive contribution','Return the sum of all **strictly positive** values in nums. Zero and negative values contribute nothing. For an empty array return 0. The total can exceed a 32-bit integer.',['algorithms','edge_cases'],[([4,-2,7,0],11,'Mixed values'),([],0,'Empty input'),([-4,-1],0,'Only negatives'),([2147483647,2147483647],4294967294,'Large sum'),([1,1,1],3,'Repeated positives')],{'python':'def solve(nums):\n    return sum(n for n in nums if n > 0)','javascript':'function solve(nums) { return nums.filter(n=>n>0).reduce((a,b)=>a+b,0); }','java':'class Solution { public static Object solve(int[] nums) { long sum=0;for(int n:nums)if(n>0)sum+=n;return sum; } }'}),
        ('unique-count','Count what is different','Return the number of distinct integers in nums. Repeated occurrences count only once. For an empty array return 0. Input may contain negative numbers and zero.',['collections','edge_cases'],[([1,2,2,3],3,'Repeated values'),([],0,'Empty input'),([0,0,0],1,'All zero'),([-2,-2,1],2,'Mixed signs'),([9,8,7,6],4,'All distinct')],{'python':'def solve(nums):\n    return len(set(nums))','javascript':'function solve(nums) { return new Set(nums).size; }','java':'class Solution { public static Object solve(int[] nums) { java.util.HashSet<Integer> s=new java.util.HashSet<>();for(int n:nums)s.add(n);return s.size(); } }'}),
    ]
    for slug,title,statement,comps,tests,refs in tasks:
        write(dict(slug=lang+'-'+slug,skill=lang,family=lang+'.'+slug,type='coding',title=title,statement=statement,competencies=comps,language=lang,starter=starters[lang],reference=refs[lang],hints=['Trace the simplest input before coding.','Consider empty arrays, duplicates, and negative values.','A set separates distinct values from occurrences.'],tests=[dict(input=inp,expected=ex,label=label,visibility='sample' if i==0 else 'hidden',competencies=comps) for i,(inp,ex,label) in enumerate(tests)]))
    refs=tasks[1][-1]
    buggy={'python':'def solve(nums):\n    return sum(nums)\n','javascript':'function solve(nums) { return nums.reduce((a,b)=>a+b,0); }','java':'class Solution { public static Object solve(int[] nums) { long sum=0;for(int n:nums)sum+=n;return sum; } }'}
    write(dict(slug=lang+'-debug-positive',skill=lang,family=lang+'.debug-positive',type='debugging',title='The refund that reduced the total',statement='A report should sum **strictly positive** amounts, but negative adjustments are reducing the result. Fix solve(nums), returning 0 for an empty array. Preserve correct behavior for ordinary positive values and use a sufficiently large numeric type.',competencies=['algorithms','edge_cases'],language=lang,starter=buggy[lang],reference=refs[lang],hints=['Compare the stated behavior with what the loop includes.','A value must satisfy a condition before it contributes.'],tests=[dict(input=inp,expected=ex,label=label,visibility='sample' if i==0 else 'hidden',competencies=['algorithms','edge_cases']) for i,(inp,ex,label) in enumerate(tasks[1][4])]))
    suggestions={
        'python':['def solve(nums):\n    return sum(nums) / len(nums) if nums else 0','def solve(nums):\n    return sum(nums) / len(nums)','def solve(nums):\n    return sum(nums) // len(nums) if nums else 0'],
        'javascript':['function solve(nums) { return nums.length ? nums.reduce((a,b)=>a+b,0)/nums.length : 0; }','function solve(nums) { return nums.reduce((a,b)=>a+b,0)/nums.length; }','function solve(nums) { return nums.length ? Math.trunc(nums.reduce((a,b)=>a+b,0)/nums.length) : 0; }'],
        'java':['class Solution { public static Object solve(int[] nums) { if(nums.length==0)return 0.0;long s=0;for(int n:nums)s+=n;return (double)s/nums.length; } }','class Solution { public static Object solve(int[] nums) { long s=0;for(int n:nums)s+=n;return (double)s/nums.length; } }','class Solution { public static Object solve(int[] nums) { if(nums.length==0)return 0.0;long s=0;for(int n:nums)s+=n;return s/nums.length; } }']}
    codes=suggestions[lang]
    write(dict(slug=lang+'-trust-average',skill=lang,family=lang+'.trust-average',type='trust',minutes=15,title='Would you ship this average?',statement='Review three suggestions for solve(nums). It must return the arithmetic mean **without losing the fractional part**, and return 0 for an empty array. Integers are between -1,000,000 and 1,000,000. Judge each suggestion, provide a counterexample and expected result, then fix the implementation.',competencies=['edge_cases','algorithms'],language=lang,starter=codes[1],reference=codes[0],categories=['correct','edge_case_failure','logic_defect'],suggestions=[dict(id='option-'+str(i+1),code=code,acceptable=i==0,category=['correct','edge_case_failure','logic_defect'][i]) for i,code in enumerate(codes)],tests=[dict(input=x,expected=y,label=label,visibility='hidden',competencies=['edge_cases','algorithms']) for x,y,label in [([],0,'Empty input'),([1,2],1.5,'Fractional result'),([-2,2],0,'Mixed signs'),([1000000,1000000],1000000,'Large values')]],hints=['What happens when the list is empty?','What kind of division preserves a fraction?']))

for lang in ['sql','python','java','javascript']:
    comps=['duplicates','null_handling'] if lang=='sql' else ['collections','algorithms']
    write(dict(slug=lang+'-scenario-retries',skill=lang,family=lang+'.scenario-retries',type='scenario',minutes=8,title='One payment, many retries',statement='A payment provider retries a webhook when your endpoint times out. Two requests can arrive at the same time. Your database now contains duplicate payments with the same provider transaction ID. Choose a strategy that remains correct under concurrency.',competencies=comps,questions=[dict(id='prevention',prompt='Which prevention strategy is reliable under concurrent requests?',options=[dict(id='unique',text='A unique provider transaction ID with an atomic upsert'),dict(id='select',text='Check with SELECT, then INSERT if absent'),dict(id='timeout',text='Increase the HTTP timeout')]),dict(id='cleanup',prompt='How should existing duplicates be cleaned up?',options=[dict(id='transaction',text='Back up, retain one canonical row per transaction, clean up transactionally, then add the constraint'),dict(id='all',text='Delete every payment and retry all webhooks'),dict(id='ignore',text='Leave existing duplicates and only fix new requests')]),dict(id='null',prompt='What else must the transaction identifier rule establish?',options=[dict(id='required',text='The identifier is required and validated, with explicit handling of missing values'),dict(id='any',text='All missing identifiers refer to the same payment'),dict(id='client',text='The browser alone can enforce uniqueness')])],answers={'prevention':'unique','cleanup':'transaction','null':'required'},hints=['Think about two requests passing the same check at the same time.']))

